# Functions

linpeas_json_escape(){
  printf "%s" "$1" | sed 's/\\/\\\\/g; s/"/\\"/g; s/	/ /g'
}
linpeas_os_release_field(){
  [ -r /etc/os-release ] || return
  awk -F= -v key="$1" '
    $1 == key {
      value=$0
      sub(/^[^=]*=/, "", value)
      gsub(/^"/, "", value)
      gsub(/"$/, "", value)
      print value
      exit
    }
  ' /etc/os-release 2>/dev/null
}
linpeas_os_package_ecosystem(){
  _os_id="$(linpeas_os_release_field ID)"
  _os_version_id="$(linpeas_os_release_field VERSION_ID)"
  _os_version_major="$(printf "%s" "$_os_version_id" | cut -d. -f1)"
  case "$_os_id" in
    debian)  [ "$_os_version_major" ] && printf "Debian:%s" "$_os_version_major" ;;
    ubuntu)  [ "$_os_version_id" ] && printf "Ubuntu:%s" "$_os_version_id" ;;
    alpine)  [ "$_os_version_id" ] && printf "Alpine:v%s" "$_os_version_id" ;;
    fedora)  [ "$_os_version_id" ] && printf "Fedora:%s" "$_os_version_id" ;;
    amzn)    [ "$_os_version_id" ] && printf "Amazon Linux:%s" "$_os_version_id" ;;
    rhel)    [ "$_os_version_major" ] && printf "Red Hat:%s" "$_os_version_major" ;;
    centos)  [ "$_os_version_major" ] && printf "CentOS:%s" "$_os_version_major" ;;
    rocky)   [ "$_os_version_major" ] && printf "Rocky Linux:%s" "$_os_version_major" ;;
    almalinux) [ "$_os_version_major" ] && printf "AlmaLinux:%s" "$_os_version_major" ;;
  esac
}
linpeas_tabbed_packages_to_json_lines(){
  awk -F '\t' -v manager="$1" -v ecosystem="$2" '
    function esc(s) { gsub(/\\/,"\\\\",s); gsub(/"/,"\\\"",s); gsub(/\r/," ",s); return s }
    $1 != "" && $2 != "" {
      key=$1 "|" $2
      if (seen[key]++) next
      printf "{\"name\":\"%s\",\"version\":\"%s\",\"ecosystem\":\"%s\",\"manager\":\"%s\"}\n", esc($1), esc($2), esc(ecosystem), manager
    }'
}
linpeas_print_package_json_lines(){
  _ecosystem="$(linpeas_os_package_ecosystem)"
  if command -v dpkg-query >/dev/null 2>&1; then
    dpkg-query -W -f='${source:Package}\t${source:Version}\t${binary:Package}\t${Version}\n' 2>/dev/null | awk -F '\t' '
      {
        name=$1; version=$2
        if (name == "" || name == "-") { name=$3; version=$4 }
        if (version == "" || version == "-") { version=$4 }
        sub(/^src:/, "", name)
        if (name == "" || version == "") next
        printf "%s\t%s\n", name, version
      }' | linpeas_tabbed_packages_to_json_lines "dpkg" "$_ecosystem"
  elif command -v rpm >/dev/null 2>&1; then
    rpm -qa --qf '%{NAME}\t%{VERSION}-%{RELEASE}\n' 2>/dev/null | linpeas_tabbed_packages_to_json_lines "rpm" "$_ecosystem"
  elif command -v apk >/dev/null 2>&1; then
    apk info 2>/dev/null | while IFS= read -r _pkg_name; do
      [ "$_pkg_name" ] || continue
      _pkg_line="$(apk info -e -v "$_pkg_name" 2>/dev/null | head -n 1)"
      _pkg_version="$(printf "%s" "$_pkg_line" | awk -v n="$_pkg_name" 'index($0, n "-") == 1 { print substr($0, length(n) + 2); exit }')"
      [ "$_pkg_version" ] || continue
      printf '{"name":"%s","version":"%s","ecosystem":"%s","manager":"apk"}\n' \
        "$(linpeas_json_escape "$_pkg_name")" "$(linpeas_json_escape "$_pkg_version")" "$(linpeas_json_escape "$_ecosystem")"
    done
  elif command -v pacman >/dev/null 2>&1; then
    pacman -Q 2>/dev/null | linpeas_tabbed_packages_to_json_lines "pacman" "$_ecosystem"
  fi
}
linpeas_packages_json(){
  _limit="${HACKTRICKS_PACKAGE_LIMIT:-300}"
  linpeas_print_package_json_lines | awk -v max="$_limit" '
    BEGIN { first=1; printf "[" }
    NF {
      if (count >= max) next
      if (!first) printf ","
      printf "%s", $0
      first=0
      count++
    }
    END { printf "]" }'
}
linpeas_os_json(){
  _os_id="$(linpeas_os_release_field ID)"
  _os_name="$(linpeas_os_release_field PRETTY_NAME)"
  _os_version_id="$(linpeas_os_release_field VERSION_ID)"
  _os_codename="$(linpeas_os_release_field VERSION_CODENAME)"
  printf '{"id":"%s","name":"%s","version_id":"%s","codename":"%s","kernel":{"release":"%s","version":"%s","arch":"%s"}}' \
    "$(linpeas_json_escape "$_os_id")" \
    "$(linpeas_json_escape "$_os_name")" \
    "$(linpeas_json_escape "$_os_version_id")" \
    "$(linpeas_json_escape "$_os_codename")" \
    "$(linpeas_json_escape "$(uname -r 2>/dev/null)")" \
    "$(linpeas_json_escape "$(uname -v 2>/dev/null)")" \
    "$(linpeas_json_escape "$(uname -m 2>/dev/null)")"
}
linpeas_host_checker_payload(){
  _hostname="$(hostname 2>/dev/null)"
  if [ "$ONLINE_VULN_CHECKS" ]; then
    printf '{"hostname":"%s","source":"linpeas","version":"%s","online_package_check":true,"os":%s,"packages":%s}' \
      "$(linpeas_json_escape "$_hostname")" \
      "$(linpeas_json_escape "$VERSION")" \
      "$(linpeas_os_json)" \
      "$(linpeas_packages_json)"
  else
    printf '{"hostname":"%s","source":"linpeas","version":"%s"}' \
      "$(linpeas_json_escape "$_hostname")" \
      "$(linpeas_json_escape "$VERSION")"
  fi
}
linpeas_start_host_checker_lookup(){
  [ "$NOT_CHECK_EXTERNAL_HOSTNAME" ] && return
  [ "$LINPEAS_HOST_CHECKER_STARTED" ] && return
  INTERNET_SEARCH_TIMEOUT=15
  LINPEAS_HOST_CHECKER_STARTED="1"
  LINPEAS_HOST_CHECKER_OUT="${TMPDIR:-/tmp}/linpeas_host_checker_$$.json"
  LINPEAS_HOST_CHECKER_ERR="${TMPDIR:-/tmp}/linpeas_host_checker_$$.err"
  _hacktricks_host_checker_url="${HACKTRICKS_HOST_CHECKER_URL:-https://tools.hacktricks.wiki/api/host-checker}"
  _hacktricks_payload="$(linpeas_host_checker_payload)"
  if command -v curl >/dev/null 2>&1; then
    (curl -s "$_hacktricks_host_checker_url" -H "User-Agent: linpeas" --data-binary "$_hacktricks_payload" -H "Content-Type: application/json" --max-time "$INTERNET_SEARCH_TIMEOUT" > "$LINPEAS_HOST_CHECKER_OUT" 2>"$LINPEAS_HOST_CHECKER_ERR") &
    LINPEAS_HOST_CHECKER_PID=$!
  elif command -v wget >/dev/null 2>&1; then
    (wget -q -O - "$_hacktricks_host_checker_url" --header "User-Agent: linpeas" --header "Content-Type: application/json" --post-data "$_hacktricks_payload" --timeout "$INTERNET_SEARCH_TIMEOUT" > "$LINPEAS_HOST_CHECKER_OUT" 2>"$LINPEAS_HOST_CHECKER_ERR") &
    LINPEAS_HOST_CHECKER_PID=$!
  else
    printf '{"error":"wget or curl not found"}\n' > "$LINPEAS_HOST_CHECKER_OUT"
  fi
}
linpeas_wait_host_checker_lookup(){
  [ "$NOT_CHECK_EXTERNAL_HOSTNAME" ] && return 1
  linpeas_start_host_checker_lookup
  if [ "$LINPEAS_HOST_CHECKER_PID" ]; then
    wait "$LINPEAS_HOST_CHECKER_PID" 2>/dev/null
    LINPEAS_HOST_CHECKER_PID=""
  fi
  [ -s "$LINPEAS_HOST_CHECKER_OUT" ]
}
linpeas_strip_package_vulns_from_host_response(){
  if command -v jq >/dev/null 2>&1; then
    jq 'del(.package_vulnerabilities)' "$LINPEAS_HOST_CHECKER_OUT" 2>/dev/null && return
  fi
  awk '
    function brace_delta(s, t, opens, closes) {
      t=s; opens=gsub(/{/,"{",t)
      t=s; closes=gsub(/}/,"}",t)
      return opens - closes
    }
    skip {
      depth += brace_delta($0)
      if (depth <= 0) skip=0
      next
    }
    /"package_vulnerabilities"[[:space:]]*:/ {
      sub(/,[[:space:]]*$/, "", prev)
      skip=1
      depth=brace_delta($0)
      if (depth <= 0) skip=0
      next
    }
    {
      if (have) print prev
      prev=$0
      have=1
    }
    END {
      if (have) print prev
    }
  ' "$LINPEAS_HOST_CHECKER_OUT"
}
check_external_hostname(){
  if linpeas_wait_host_checker_lookup; then
    linpeas_strip_package_vulns_from_host_response
  else
    echo "HackTricks host checker did not return data"
  fi
}
linpeas_print_package_vulnerabilities_with_jq(){
  jq -r '
    .package_vulnerabilities as $pv
    | if ($pv == null) then
        empty
      elif (($pv.affected // 0) | tonumber) == 0 then
        "No vulnerable packages found by online lookup (checked \($pv.checked // 0) packages)."
      else
        "Online package vulnerabilities found: \($pv.affected) vulnerable package(s), checked \($pv.checked // 0).",
        (
          $pv.vulnerable_packages[:50][]?
          | "- \(.name // "?") \(.version // "?") [\(.ecosystem // "unknown")]: \((.vulns // []) | join(", "))"
        ),
        (
          if (($pv.vulnerable_packages | length) > 50) then
            "... \((($pv.vulnerable_packages | length) - 50)) more vulnerable package(s) not shown."
          else empty end
        )
      end
  ' "$LINPEAS_HOST_CHECKER_OUT" 2>/dev/null
}
linpeas_print_package_vulnerabilities_with_awk(){
  awk '
    function json_value(line) {
      sub(/^[^:]*:[[:space:]]*"/, "", line)
      sub(/",?[[:space:]]*$/, "", line)
      return line
    }
    function json_number(line) {
      sub(/^[^:]*:[[:space:]]*/, "", line)
      sub(/,?[[:space:]]*$/, "", line)
      return line
    }
    function json_string(line) {
      sub(/^[[:space:]]*"/, "", line)
      sub(/",?[[:space:]]*$/, "", line)
      return line
    }
    function flush_pkg() {
      if (name != "" && version != "") {
        total++
        if (shown < 50) {
          print "- " name " " version " [" (ecosystem != "" ? ecosystem : "unknown") "]: " vulns
          shown++
        }
      }
      name=""; version=""; ecosystem=""; vulns=""; in_vulns=0
    }
    /"package_vulnerabilities"[[:space:]]*:/ { in_pv=1; next }
    in_pv && /"checked"[[:space:]]*:/ { checked=json_number($0); next }
    in_pv && /"affected"[[:space:]]*:/ { affected=json_number($0); next }
    in_pv && /"vulnerable_packages"[[:space:]]*:[[:space:]]*\[/ { in_pkgs=1; next }
    in_pkgs && /"name"[[:space:]]*:/ { name=json_value($0); next }
    in_pkgs && /"version"[[:space:]]*:/ { version=json_value($0); next }
    in_pkgs && /"ecosystem"[[:space:]]*:/ { ecosystem=json_value($0); next }
    in_pkgs && /"vulns"[[:space:]]*:[[:space:]]*\[/ { in_vulns=1; next }
    in_vulns && /"/ {
      v=json_string($0)
      if (v != "") vulns = vulns (vulns != "" ? ", " : "") v
      next
    }
    in_vulns && /\]/ { in_vulns=0; next }
    in_pkgs && /^[[:space:]]*}[,]?[[:space:]]*$/ { flush_pkg(); next }
    END {
      if (affected == "") exit
      if ((affected + 0) == 0) {
        print "No vulnerable packages found by online lookup (checked " (checked != "" ? checked : 0) " packages)."
      } else {
        print "Online package vulnerabilities found: " affected " vulnerable package(s), checked " (checked != "" ? checked : 0) "."
        if (total > 50) print "... " (total - 50) " more vulnerable package(s) not shown."
      }
    }
  ' "$LINPEAS_HOST_CHECKER_OUT" | awk '
    /^Online package vulnerabilities found:/ { header=$0; next }
    /^No vulnerable packages found/ { print; next }
    /^\.\.\. / { more=$0; next }
    /^- / { lines[++count]=$0; next }
    END {
      if (header) print header
      for (i=1; i<=count && i<=50; i++) print lines[i]
      if (more) print more
    }
  '
}
linpeas_print_package_vulnerabilities(){
  [ "$ONLINE_VULN_CHECKS" ] || return
  if ! linpeas_wait_host_checker_lookup; then
    echo "Online package vulnerability lookup did not return data"
    return
  fi
  if command -v jq >/dev/null 2>&1; then
    linpeas_print_package_vulnerabilities_with_jq | sed -${E} "s,CVE-[0-9]{4}-[0-9]+,${SED_RED_YELLOW},g"
  else
    linpeas_print_package_vulnerabilities_with_awk | sed -${E} "s,CVE-[0-9]{4}-[0-9]+,${SED_RED_YELLOW},g"
  fi
}

echo_not_found(){
  printf $DG"$1 Not Found\n"$NC
}

warn_exec(){
  $* 2>/dev/null || echo_not_found $1
}

pgbb_mount_options() {
  [ -r /proc/mounts ] || return 1
  awk -v path="$1" '
    $2 !~ /\\\\/ && (path == $2 || $2 == "/" || index(path, $2 "/") == 1) {
      if (length($2) > best) { best=length($2); opts=$4 }
    }
    END { if (best) print opts }
  ' /proc/mounts
}

print_info(){
  printf "${BLUE}╚ ${ITALIC_BLUE}$1\n"$NC
}

checkGlibcTunablesCVE20234911() {
  command -v dpkg-query >/dev/null 2>&1 || return 0
  command -v dpkg >/dev/null 2>&1 || return 0
  gt4911_root="${ROOT_FOLDER:-/}"
  case "$gt4911_root" in */) ;; *) gt4911_root="$gt4911_root/" ;; esac
  gt4911_release="${gt4911_root}etc/os-release"
  [ -r "$gt4911_release" ] || return 0
  gt4911_id="$(sed -n 's/^ID=//p' "$gt4911_release" | head -n 1 | tr -d '"')"
  gt4911_codename="$(sed -n 's/^VERSION_CODENAME=//p' "$gt4911_release" | head -n 1 | tr -d '"')"
  # Compare vendor package releases, not upstream glibc versions: Debian
  # bullseye backported the affected parser into its older 2.31 package.
  case "$gt4911_id:$gt4911_codename" in
    ubuntu:jammy) gt4911_fixed="2.35-0ubuntu3.4" ;;
    ubuntu:lunar) gt4911_fixed="2.37-0ubuntu2.1" ;;
    ubuntu:mantic|ubuntu:noble) gt4911_fixed="2.38-1ubuntu6" ;;
    debian:bullseye) gt4911_fixed="2.31-13+deb11u7" ;;
    debian:bookworm) gt4911_fixed="2.36-9+deb12u3" ;;
    *) return 0 ;;
  esac
  gt4911_record="$(dpkg-query --admindir="${gt4911_root}var/lib/dpkg" -W -f='$''{Status}|$''{Version}\n' libc6 2>/dev/null | head -n 1)"
  case "$gt4911_record" in
    'install ok installed|'*) gt4911_version="${gt4911_record#*|}" ;;
    *) return 0 ;;
  esac
  [ -n "$gt4911_version" ] || return 0
  print_3title "GNU C Library tunables package review (CVE-2023-4911)" "T1068"
  print_info "https://ubuntu.com/security/CVE-2023-4911"
  print_info "https://security-tracker.debian.org/tracker/CVE-2023-4911"
  echo "Installed libc6: $gt4911_version; vendor fixed threshold for $gt4911_id $gt4911_codename: $gt4911_fixed"
  if dpkg --compare-versions "$gt4911_version" lt "$gt4911_fixed"; then
    echo "Package below vendor fix: review candidate only. Confirm installed loader, package patch state, a reachable SUID target, and NoNewPrivs/nosuid or other mitigations; no exploit probe was run."
  else
    echo "Installed package meets this vendor's fixed threshold; confirm the running loader after package updates."
  fi
}

lp_extract_upstream_version() {
  printf '%s' "$1" | sed -E 's/^[0-9]+://; s/^[^0-9]*//; s/[^0-9.].*$//'
}

lp_trusted_version_path() { (
  # Never execute a program solely because a readable configuration names it.
  # Execute the checked canonical path, not a replaceable symlink spelling.
  case "$1" in /*) ;; *) exit 1 ;; esac
  lp_version_path=$(readlink -f "$1" 2>/dev/null) ||
    lp_version_path=$(realpath "$1" 2>/dev/null) || exit 1
  case "$lp_version_path" in /*) ;; *) exit 1 ;; esac
  [ "${#lp_version_path}" -le 4096 ] &&
    [ -f "$lp_version_path" ] && [ -x "$lp_version_path" ] || exit 1
  lp_version_uid=$(id -u 2>/dev/null) || exit 1
  lp_version_walk=$lp_version_path
  lp_version_count=0
  while :; do
    lp_version_count=$((lp_version_count + 1))
    [ "$lp_version_count" -le 64 ] && [ ! -L "$lp_version_walk" ] || exit 1
    # Numeric ownership and symbolic mode work on GNU, BSD and BusyBox ls.
    LC_ALL=C ls -ldn "$lp_version_walk" 2>/dev/null | awk '
      NR == 1 && $3 == "0" && length($1) >= 10 &&
          substr($1, 6, 1) != "w" && substr($1, 9, 1) != "w" { safe = 1 }
      END { exit !safe }
    ' || exit 1
    if [ "$lp_version_uid" != 0 ] && [ -w "$lp_version_walk" ]; then exit 1; fi
    [ "$lp_version_walk" != / ] || break
    lp_version_walk=${lp_version_walk%/*}
    [ -n "$lp_version_walk" ] || lp_version_walk=/
  done
  printf '%s\n' "$lp_version_path"
) }

check_privileged_file_location() {
  priv_file_type="$1"
  priv_file_name="$2"
  priv_file_owner="$3"
  priv_file_unusual=""
  case "$priv_file_name" in
    "${ROOT_FOLDER}tmp/"*|"${ROOT_FOLDER}var/tmp/"*|"${ROOT_FOLDER}dev/shm/"*|"${ROOT_FOLDER}run/user/"*|"${ROOT_FOLDER}var/run/user/"*|"${ROOT_FOLDER}home/"*)
      echo "$priv_file_type file in a user-writable or unusual location: $priv_file_name" | sed -${E} "s,.*,${SED_RED_YELLOW},"
      priv_file_unusual="1"
      ;;
  esac
  if [ "$priv_file_owner" = root ] && [ -f "$priv_file_name" ] && [ ! -L "$priv_file_name" ] && [ -x "$priv_file_name" ]; then
    while IFS= read -r priv_backup_dest; do
      [ -n "$priv_backup_dest" ] || continue
      case "$priv_file_name" in
        "$priv_backup_dest"/*)
          priv_backup_opts=$(pgbb_mount_options "$priv_file_name")
          case ",$priv_backup_opts," in ,,|*,nosuid,*|*,noexec,*) continue ;; esac
          echo "$priv_file_type root-owned file under a reviewed PostgreSQL backup destination: $priv_file_name" | sed -${E} "s,.*,${SED_RED_YELLOW},"
          priv_file_unusual=1
          break
          ;;
      esac
    done <<EOF_PRIV_BACKUP_DESTS
$PG_BASEBACKUP_DESTS
EOF_PRIV_BACKUP_DESTS
  fi
  priv_file_parent="$(dirname "$priv_file_name")"
  if ! [ "$IAMROOT" ] && [ -d "$priv_file_parent" ] && [ -w "$priv_file_parent" ] && [ -x "$priv_file_parent" ] && ! [ -k "$priv_file_parent" ]; then
    echo "You can replace entries in the $priv_file_type file's parent directory: $priv_file_parent" | sed -${E} "s,.*,${SED_RED_YELLOW},"
  fi
  if [ "$priv_file_owner" ] && [ "$priv_file_owner" != "root" ]; then
    echo "$priv_file_type file is owned by non-root user $priv_file_owner: $priv_file_name" | sed -${E} "s,.*,${SED_RED},"
  fi
  if [ "$priv_file_unusual" ] && find "$priv_file_name" -mtime -7 -print 2>/dev/null | grep -q .; then
    echo "$priv_file_type file in an unusual location was modified in the last 7 days: $priv_file_name" | sed -${E} "s,.*,${SED_RED},"
  fi
}

sc8933_version_ge() {
  [ -n "$1" ] && [ -n "$2" ] || return 1
  if command -v dpkg >/dev/null 2>&1; then
    dpkg --compare-versions "$1" ge "$2"
  else
    [ "$(printf '%s\n%s\n' "$1" "$2" | sort -V 2>/dev/null | tail -n1)" = "$1" ]
  fi
}
sc8933_version_lt() {
  [ -n "$1" ] && [ -n "$2" ] || return 1
  if command -v dpkg >/dev/null 2>&1; then
    dpkg --compare-versions "$1" lt "$2"
  else
    [ "$1" != "$2" ] && [ "$(printf '%s\n%s\n' "$1" "$2" | sort -V 2>/dev/null | head -n1)" = "$1" ]
  fi
}
sc8933_version_is_vulnerable() {
  sc8933_version="$1"
  sc8933_kind="$2"
  sc8933_os_release="$3"
  sc8933_upstream="$(lp_extract_upstream_version "$sc8933_version")"
  # The upstream affected range is >= 2.75.0 and < 2.76.1. Ubuntu fixed
  # 2.76 with release-specific backports, so compare the complete dpkg version.
  sc8933_version_ge "$sc8933_upstream" "2.75" || return 1
  if [ "$sc8933_kind" = "deb" ]; then
    sc8933_fixed=""
    case "$sc8933_os_release" in
      22.04) sc8933_fixed="2.76+ubuntu22.04.1" ;;
      24.04) sc8933_fixed="2.76+ubuntu24.04.1" ;;
      26.04) sc8933_fixed="2.76+ubuntu26.04.3" ;;
    esac
    if [ -n "$sc8933_fixed" ]; then
      sc8933_version_lt "$sc8933_version" "$sc8933_fixed"
      return
    fi
  fi
  sc8933_version_lt "$sc8933_upstream" "2.76.1"
}
checkSnapConfineCVE20268933() {
  command -v getcap >/dev/null 2>&1 || return
  sc8933_root="${ROOT_FOLDER:-/}"
  case "$sc8933_root" in
    */) ;;
    *) sc8933_root="${sc8933_root}/" ;;
  esac
  sc8933_os_id="$(sed -nE 's/^ID="?([^" ]+)"?$/\1/p' "${sc8933_root}etc/os-release" 2>/dev/null | head -n1)"
  sc8933_os_release="$(sed -nE 's/^VERSION_ID="?([^" ]+)"?$/\1/p' "${sc8933_root}etc/os-release" 2>/dev/null | head -n1)"
  sc8933_reported=""
  for sc8933_path in \
    "${sc8933_root}usr/lib/snapd/snap-confine" \
    "${sc8933_root}snap/snapd/current/usr/lib/snapd/snap-confine"; do
    [ -f "$sc8933_path" ] || continue
    [ -u "$sc8933_path" ] && continue
    sc8933_caps="$(getcap "$sc8933_path" 2>/dev/null)"
    printf '%s' "$sc8933_caps" | grep -q 'cap_sys_admin' || continue
    if [ -z "$sc8933_reported" ]; then
      print_3title "Set-capabilities snap-confine (CVE-2026-8933)" "T1068"
      print_info "https://ubuntu.com/security/CVE-2026-8933"
      sc8933_reported="1"
    fi
    sc8933_kind="snap"
    sc8933_yaml="${sc8933_root}snap/snapd/current/meta/snap.yaml"
    sc8933_version=""
    case "$sc8933_path" in
      */usr/lib/snapd/snap-confine)
        if [ "$sc8933_path" = "${sc8933_root}usr/lib/snapd/snap-confine" ]; then
          sc8933_kind="deb"
          if command -v dpkg-query >/dev/null 2>&1; then
            sc8933_version="$(dpkg-query --admindir="${sc8933_root}var/lib/dpkg" -W -f='$''{Version}\n' snapd 2>/dev/null | head -n1)"
          fi
        elif [ -r "$sc8933_yaml" ]; then
          sc8933_version="$(sed -nE "s/^version:[[:space:]]*['\"]?([^'\"[:space:]]+).*/\1/p" "$sc8933_yaml" 2>/dev/null | head -n1)"
        fi
        ;;
    esac
    echo "$sc8933_caps" | sed -${E} "s,.*,${SED_LIGHT_CYAN},"
    if [ -z "$sc8933_version" ]; then
      echo "Potential CVE-2026-8933 exposure: privileged snap-confine uses file capabilities; version could not be determined" | sed -${E} "s,.*,${SED_RED_YELLOW},"
    elif [ "$sc8933_os_id" != "ubuntu" ] && [ "$sc8933_kind" = "deb" ]; then
      if sc8933_version_is_vulnerable "$sc8933_version" "$sc8933_kind" "$sc8933_os_release"; then
        echo "snap-confine version $sc8933_version uses file capabilities and is in the upstream CVE-2026-8933 range; verify distro backports" | sed -${E} "s,.*,${SED_RED_YELLOW},"
      else
        echo "snap-confine version $sc8933_version is not in the known CVE-2026-8933 vulnerable range" | sed -${E} "s,.*,${SED_GREEN},"
      fi
    elif sc8933_version_is_vulnerable "$sc8933_version" "$sc8933_kind" "$sc8933_os_release"; then
      echo "Vulnerable to CVE-2026-8933: set-capabilities snap-confine version $sc8933_version permits local privilege escalation to root" | sed -${E} "s,.*,${SED_RED_YELLOW},"
    else
      echo "snap-confine version $sc8933_version is not in the known CVE-2026-8933 vulnerable range" | sed -${E} "s,.*,${SED_GREEN},"
    fi
  done
  if [ -n "$sc8933_reported" ]; then
    echo ""
  fi
}

checkSnapConfineCVE20263888() {
  sc3888_root="${ROOT_FOLDER:-/}"
  case "$sc3888_root" in */) ;; *) sc3888_root="${sc3888_root}/" ;; esac
  sc3888_path="${sc3888_root}usr/lib/snapd/snap-confine"
  [ -f "$sc3888_path" ] || return 0
  sc3888_priv=""
  if [ -u "$sc3888_path" ]; then
    sc3888_priv="setuid"
  elif command -v getcap >/dev/null 2>&1 &&
       getcap "$sc3888_path" 2>/dev/null | grep -q 'cap_sys_admin'; then
    sc3888_priv="file capabilities"
  fi
  [ -n "$sc3888_priv" ] || return 0
  sc3888_release="$(sed -n 's/^VERSION_ID="\{0,1\}\([0-9][0-9.]*\)"\{0,1\}$/\1/p' "${sc3888_root}etc/os-release" 2>/dev/null | head -n 1)"
  sc3888_version=""
  if command -v dpkg-query >/dev/null 2>&1; then
    sc3888_version="$(dpkg-query --admindir="${sc3888_root}var/lib/dpkg" -W -f='$''{Status} $''{Version}\n' snapd 2>/dev/null | awk 'NR==1 && $1=="install" && $2=="ok" && $3=="installed" {print $4; exit}')"
  fi
  sc3888_fixed=""
  case "$sc3888_release" in
    16.04) sc3888_fixed="2.61.4ubuntu0.16.04.1+esm2" ;;
    18.04) sc3888_fixed="2.61.4ubuntu0.18.04.1+esm2" ;;
    20.04) sc3888_fixed="2.67.1+20.04ubuntu1~esm1" ;;
    22.04) sc3888_fixed="2.73+ubuntu22.04.1" ;;
    24.04) sc3888_fixed="2.73+ubuntu24.04.2" ;;
    25.10) sc3888_fixed="2.73+ubuntu25.10.1" ;;
    26.04) sc3888_fixed="2.74.1+ubuntu26.04.3" ;;
  esac
  sc3888_state="unknown"
  # Compare complete Debian versions only for Ubuntu packages on a known release.
  # A local rebuild, epoch, or unexpected suffix can contain a backported fix.
  if grep -q '^ID=\("\{0,1\}\)ubuntu\1$' "${sc3888_root}etc/os-release" 2>/dev/null &&
     [ -n "$sc3888_version" ] && [ -n "$sc3888_fixed" ] &&
     command -v dpkg >/dev/null 2>&1; then
    case "$sc3888_version" in
      *"$sc3888_release"*|*"ubuntu${sc3888_release}"*)
        if dpkg --compare-versions "$sc3888_version" ge "$sc3888_fixed"; then
          sc3888_state="at-or-above-fix"
        else
          sc3888_state="below-fix"
        fi
        ;;
    esac
  fi
  # Inspect the usual effective tmp.conf by directory precedence. Other rule
  # names and runtime unit state need a full tmpfiles/systemd evaluation.
  sc3888_rule=""
  for sc3888_dir in etc run usr/local/lib usr/lib lib; do
    if [ -r "${sc3888_root}${sc3888_dir}/tmpfiles.d/tmp.conf" ]; then
      sc3888_rule="${sc3888_root}${sc3888_dir}/tmpfiles.d/tmp.conf"
      break
    fi
  done
  sc3888_age=""
  if [ -n "$sc3888_rule" ]; then
    sc3888_age="$(awk 'NR > 100 {exit} $1 ~ /^[dDqQ][!~+=-]*$/ && $2 == "/tmp" && $6 ~ /^[0-9]+[smhdwMy]*$/ {print $6; exit}' "$sc3888_rule" 2>/dev/null)"
  fi
  sc3888_timer="unit not found"
  if [ -e "${sc3888_root}usr/lib/systemd/system/systemd-tmpfiles-clean.timer" ] ||
     [ -e "${sc3888_root}lib/systemd/system/systemd-tmpfiles-clean.timer" ]; then
    sc3888_timer="unit present; runtime activation unverified"
  fi
  if [ -e "${sc3888_root}etc/systemd/system/timers.target.wants/systemd-tmpfiles-clean.timer" ]; then
    sc3888_timer="enable link present; runtime activation unverified"
  fi
  print_3title "snap-confine/tmpfiles race prerequisites (CVE-2026-3888)" "T1068"
  print_info "https://ubuntu.com/security/CVE-2026-3888"
  echo "snap-confine: $sc3888_priv ($sc3888_path)"
  echo "snapd package: ${sc3888_version:-unknown}; Ubuntu release: ${sc3888_release:-unknown}"
  case "$sc3888_state" in
    at-or-above-fix) echo "Package version is at or above the Ubuntu advisory fix ($sc3888_fixed); verify local package provenance" ;;
    below-fix) echo "Package version is below the Ubuntu advisory fix ($sc3888_fixed); verify backports" ;;
    *) echo "Package fix status unclassified; verify distribution patches and package provenance" ;;
  esac
  if [ -n "$sc3888_age" ]; then
    echo "/tmp cleanup rule: age $sc3888_age ($sc3888_rule)"
  else
    echo "/tmp cleanup rule: not confirmed in standard tmp.conf locations"
  fi
  echo "systemd-tmpfiles-clean.timer: $sc3888_timer"
  if [ "$sc3888_state" = "below-fix" ] && [ -n "$sc3888_age" ] &&
     [ "$sc3888_timer" != "unit not found" ]; then
    echo "Potential CVE-2026-3888 prerequisites observed; timer activity, snap layout, and backports remain unverified" | sed -${E} "s,.*,${SED_RED_YELLOW},"
  fi
  echo ""
}

check_critial_root_path(){
  folder_path="$1"
  if [ -w "$folder_path" ]; then echo "You have write privileges over $folder_path" | sed -${E} "s,.*,${SED_RED_YELLOW},"; fi
  folder_writable_files=$(find "$folder_path" -type f '(' '(' -user "$USER" ')' -or '(' -perm -o=w ')' -or '(' -perm -g=w -and '(' $wgroups ')' ')' ')' 2>/dev/null) || :
  if [ "$folder_writable_files" ]; then echo "You have write privileges over $folder_writable_files" | sed -${E} "s,.*,${SED_RED_YELLOW},"; fi
  folder_nonroot_files=$(find "$folder_path" -type f -not -user root 2>/dev/null) || :
  if [ "$folder_nonroot_files" ]; then echo "The following files aren't owned by root: $folder_nonroot_files"; fi
}




